import 'dart:convert';

// OLD implementation (pre-PR switch ladder)
String oldTypeName(Object? value) => switch (value) {
  null => 'nothing',
  String() => 'a string',
  int() || double() => 'a number',
  bool() => 'a boolean',
  Map() => 'an object',
  List() => 'an array',
  _ => value.runtimeType.toString(),
};

// NEW implementation (as in the PR)
const _scalarTypeNames = <Type, String>{
  String: 'a string',
  int: 'a number',
  double: 'a number',
  bool: 'a boolean',
};

String newTypeName(Object? value) {
  if (value == null) return 'nothing';
  final named = _scalarTypeNames[value.runtimeType];
  if (named != null) return named;
  if (value is Map) return 'an object';
  if (value is List) return 'an array';
  return value.runtimeType.toString();
}

void check(Object? value, {bool viaJson = false}) {
  final o = oldTypeName(value);
  final n = newTypeName(value);
  final tag = viaJson ? 'json' : 'raw';
  print(
    '${o == n ? "OK " : "MISMATCH"} [$tag] $value -> old="$o" new="$n"',
  );
}

void main() {
  // Raw (public parseProviderQueueEntries accepts any Object?)
  check(null);
  check('x');
  check(42);
  check(1.5);
  check(true);
  check(false);
  check({'a': 1});
  check(<String, dynamic>{});
  check([1, 2]);
  check(<int>[]);
  check(Object());
  check(DateTime.utc(2026));
  check({1: {2: 3}});
  check([[1], [2]]);
  check(const {'k': 'v'});
  check(utf8.decode([104, 105]));
  // JSON-decoded domain (the env/file parse path)
  for (final text in [
    'null', '"s"', '42', '1.5', 'true', '{}', '[]',
    '{"a": [1, {"b": null}]}', '[{"a": 1}, "x", 3, null, true]',
  ]) {
    check(jsonDecode(text), viaJson: true);
  }
  // Raw bytes (Uint8List — a List subclass with a specific runtimeType)
  // ignore: avoid_print
  print('done');
}

